css:
.tpl-hf-workflow-approve { position: relative; width: 100%; height: 100%; overflow: hidden; display: flex; flex-direction: column; align-items: center; justify-content: center; background: radial-gradient(ellipse 75% 75% at 50% 45%, rgba(124,58,237,0.22) 0%, transparent 65%), var(--bg, #0d0a1a); font-family: var(--font-sans, 'Inter', 'PingFang SC', sans-serif); color: var(--fg, #ffffff); }
.tpl-hf-workflow-approve .wf-headline { position: relative; z-index: 3; font-size: clamp(26px, 4.4vmin, 56px); font-weight: 800; letter-spacing: -0.02em; margin-bottom: clamp(18px, 3.6vh, 42px); text-align: center; padding: 0 5%; opacity: 0; }
.tpl-hf-workflow-approve .wf-stage { position: relative; z-index: 2; width: 90%; max-width: 1520px; display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: clamp(18px, 3vw, 48px); }
.tpl-hf-workflow-approve .steps-flank { flex: 0 1 280px; display: flex; flex-direction: column; gap: clamp(14px, 2.4vh, 26px); transform: perspective(800px) rotateY(10deg); }
.tpl-hf-workflow-approve .step { display: flex; align-items: center; gap: 14px; opacity: 0; }
.tpl-hf-workflow-approve .step-circle { width: 38px; height: 38px; border-radius: 50%; display: flex; align-items: center; justify-content: center; border: 2px solid rgba(255,255,255,0.25); flex-shrink: 0; font-size: 15px; font-weight: 700; color: rgba(255,255,255,0.65); }
.tpl-hf-workflow-approve .step-check { display: none; }
.tpl-hf-workflow-approve .step-label { font-size: clamp(15px, 2vmin, 22px); color: var(--muted, #cbd5e1); font-weight: 500; }
.tpl-hf-workflow-approve .step[data-state="active"] .step-circle { border-color: var(--accent, #8b5cf6); color: var(--accent, #a78bfa); box-shadow: 0 0 16px rgba(139,92,246,0.55); }
.tpl-hf-workflow-approve .step[data-state="active"] .step-label { color: #ffffff; font-weight: 700; }
.tpl-hf-workflow-approve .step[data-state="complete"] .step-circle { border-color: #22c55e; background: #22c55e; color: #ffffff; }
.tpl-hf-workflow-approve .step[data-state="complete"] .step-num { display: none; }
.tpl-hf-workflow-approve .step[data-state="complete"] .step-check { display: inline-flex; }
.tpl-hf-workflow-approve .demo-frame { flex: 1 1 380px; max-width: 700px; min-height: clamp(200px, 36vh, 410px); border-radius: 16px; border: 1px solid rgba(167,139,250,0.38); background: linear-gradient(180deg, #1f1b3a 0%, #141026 100%); box-shadow: 0 0 44px rgba(124,58,237,0.26), 0 24px 56px rgba(0,0,0,0.5); overflow: hidden; display: grid; grid-template-rows: 42px 1fr 78px; opacity: 0; }
.tpl-hf-workflow-approve .mockup-bar { display: flex; align-items: center; gap: 8px; padding: 0 16px; background: #141026; border-bottom: 1px solid rgba(255,255,255,0.1); }
.tpl-hf-workflow-approve .dot { width: 10px; height: 10px; border-radius: 50%; }
.tpl-hf-workflow-approve .mockup-canvas { margin: 16px; border-radius: 10px; border: 1px solid rgba(255,255,255,0.1); background: linear-gradient(135deg, rgba(167,139,250,0.28), rgba(34,197,94,0.16)); display: flex; align-items: center; justify-content: center; letter-spacing: 0.16em; font-size: clamp(12px, 1.5vmin, 16px); font-weight: 700; color: rgba(255,255,255,0.72); }
.tpl-hf-workflow-approve .mockup-tl { padding: 10px 16px; display: flex; flex-direction: column; gap: 6px; border-top: 1px solid rgba(255,255,255,0.08); background: #120e22; }
.tpl-hf-workflow-approve .track { display: flex; gap: 5px; height: 18px; }
.tpl-hf-workflow-approve .tclip { border-radius: 4px; }
.tpl-hf-workflow-approve .button-flank { flex: 0 1 240px; display: flex; justify-content: center; transform: perspective(800px) rotateY(-10deg); }
.tpl-hf-workflow-approve .confirm-btn { padding: 0.7em 1.7em; border-radius: 12px; background: var(--accent, #7c3aed); box-shadow: 0 0 24px rgba(124,58,237,0.45); display: inline-flex; align-items: center; gap: 10px; font-size: clamp(18px, 2.5vmin, 28px); font-weight: 700; color: #fff; opacity: 0; white-space: nowrap; }
.tpl-hf-workflow-approve .btn-done { display: none; }
